import React, { useState, useEffect } from 'react';

const HERO_IMAGE = "https://images.unsplash.com/photo-1519225421980-715cb0215aed?q=80&w=2500&auto=format&fit=crop";

const Hero: React.FC = () => {
  const [offset, setOffset] = useState({ x: 0, y: 0 });

  useEffect(() => {
      const handleMouseMove = (e: MouseEvent) => {
          const { clientX, clientY } = e;
          const x = (clientX / window.innerWidth) * 2 - 1;
          const y = (clientY / window.innerHeight) * 2 - 1;
          setOffset({ x: x * -10, y: y * -8 });
      };
      window.addEventListener('mousemove', handleMouseMove);
      return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  const scrollToWork = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();
    const element = document.getElementById('work');
    if (element) {
        window.scrollTo({
            top: element.getBoundingClientRect().top + window.scrollY,
            behavior: "smooth"
        });
    }
  };

  return (
    <section className="relative h-screen w-full overflow-hidden flex items-center justify-center bg-[#F2F1ED]">

      {/* Background with cinematic blur-in effect */}
      <div 
        className="absolute inset-[-20px] z-0 animate-blur-in"
        style={{ transform: `translate(${offset.x}px, ${offset.y}px)` }}
      >
        <div className="absolute inset-0 bg-black/30 z-10" />
        <div className="absolute inset-0 bg-gradient-to-t from-[#FAF9F6] via-transparent to-black/20 z-10" />
        <img 
            src={HERO_IMAGE} 
            alt="Fine Art Wedding Moment" 
            className="w-full h-full object-cover"
            loading="eager"
        />
      </div>

      {/* Content Overlay */}
      <div className="relative z-20 text-center px-4 max-w-5xl mx-auto flex flex-col items-center">

        <span className="text-white/80 text-[10px] md:text-xs uppercase tracking-[0.5em] mb-8 animate-fade-in font-medium">
            Fine Art Wedding Film & Photography
        </span>

        <h1 className="text-5xl md:text-8xl lg:text-9xl font-serif text-white mb-6 tracking-tight leading-[0.95] drop-shadow-2xl">
          Euer Ja-Wort.<br />
          <span className="font-serif-alt italic text-brand font-light">Euer Erbe.</span>
        </h1>

        <div className="h-12 w-[1px] bg-brand/60 my-8"></div>

        <p className="max-w-xl text-white/90 text-lg md:text-2xl font-serif-alt italic leading-relaxed mb-12 drop-shadow-lg">
          Wir verwandeln eure kostbarsten Augenblicke in zeitlose Lichtspiele. Authentisch, elegant und voller Seele.
        </p>

        <div className="flex gap-6 animate-fade-in-delayed">
            <a 
                href="#work" 
                onClick={scrollToWork}
                className="group relative px-10 py-4 bg-white/10 backdrop-blur-md border border-white/30 hover:border-brand transition-all duration-700 rounded-full"
            >
                <span className="relative text-[10px] tracking-[0.3em] uppercase text-white group-hover:text-brand transition-colors">Portfolio entdecken</span>
            </a>
        </div>
      </div>

      {/* Aesthetic Scroll Prompt */}
      <div className="absolute bottom-12 left-1/2 -translate-x-1/2 z-20 flex flex-col items-center gap-4 text-white/60">
        <span className="text-[9px] uppercase tracking-[0.4em]">Scroll down</span>
        <div className="h-16 w-[1px] bg-gradient-to-b from-white/60 to-transparent"></div>
      </div>

      {/* Floral Accent Overlay (Subtle) */}
      <div className="absolute top-20 right-20 opacity-10 pointer-events-none animate-float hidden lg:block">
          <svg width="200" height="200" viewBox="0 0 100 100" fill="none" xmlns="http://www.w3.org/2000/svg">
              <path d="M50 10C50 10 45 35 20 40C45 45 50 70 50 70C50 70 55 45 80 40C55 35 50 10 50 10Z" stroke="white" strokeWidth="0.5"/>
          </svg>
      </div>
    </section>
  );
};

